// Replicates translate-home.ts's rewrite loop with identity "translations", so the only differences
// from the source must be locale-prefixed `link:` values. Any other diff means the regex prefix
// handling or the frontmatter gating corrupted a line.
import { readFileSync } from "node:fs";

const docs = "/Users/dwahl/Scripts/pantoken/docs";
const { LINK_KEY, TRANSLATABLE_KEY, frontmatterRange, toBackticks, toGrave } = await import(
  `${docs}/scripts/home-i18n.ts`
);

const locale = "hu";
const source = readFileSync(`${docs}/index.md`, "utf8");
const lines = source.split("\n");
const range = frontmatterRange(lines);
if (!range) throw new Error("no frontmatter");
const [start, end] = range;
const inFrontmatter = (i) => i >= start && i < end;

const localized = lines
  .map((line, index) => {
    if (!inFrontmatter(index)) return line;
    const translatable = line.match(TRANSLATABLE_KEY);
    if (translatable) {
      const [, indent, key, gap, value] = translatable;
      if (value.length === 0) return line;
      // Identity translation, but routed through the same backtick round-trip as the real script.
      const translated = toBackticks(value);
      return `${indent}${key}:${gap}${toGrave(translated)}`;
    }
    const link = line.match(LINK_KEY);
    if (link) {
      const [, indent, gap, value] = link;
      return `${indent}link:${gap}/${locale}${value}`;
    }
    return line;
  })
  .join("\n");

const before = lines;
const after = localized.split("\n");
console.log("line count:", before.length, "->", after.length);

const diffs = [];
for (let i = 0; i < Math.max(before.length, after.length); i += 1) {
  if (before[i] !== after[i]) diffs.push({ line: i + 1, before: before[i], after: after[i] });
}
console.log(`\n${diffs.length} changed line(s):`);
for (const d of diffs) {
  const kind = /^\s*(?:-\s+)?link:/.test(d.before ?? "") ? "LINK (expected)" : "!!! UNEXPECTED";
  console.log(`  ${kind} line ${d.line}`);
  console.log(`    -${d.before}`);
  console.log(`    +${d.after}`);
}

const unexpected = diffs.filter((d) => !/^\s*(?:-\s+)?link:/.test(d.before ?? ""));
console.log(
  `\nRESULT: ${unexpected.length === 0 ? "PASS — only link lines changed" : `FAIL — ${unexpected.length} non-link line(s) altered`}`,
);

// Same rewrite, on a synthetic page that actually exercises the fix: translatable keys as a list
// item's FIRST key, and body prose that mimics frontmatter.
const docs = "/Users/dwahl/Scripts/pantoken/docs";
const { LINK_KEY, TRANSLATABLE_KEY, collectHomeUnits, frontmatterRange, toBackticks, toGrave } =
  await import(`${docs}/scripts/home-i18n.ts`);

const source = [
  "---",
  "layout: home",
  "hero:",
  "  name: pantoken",
  "  text: Hero text",
  "  actions:",
  "    - text: Reordered action", // translatable key as the item's first key
  "      link: /guide/a",
  "    - link: /guide/b", // link as the item's first key
  "      text: Another action",
  "features:",
  "  - title: Reordered feature", // title as the item's first key
  "    details: Run &grave;npm i&grave; and go.",
  "---",
  "",
  "## Body",
  "",
  "- title: Markdown list, not frontmatter",
  "  text: Also body prose",
  "  link: /guide/should-not-be-prefixed",
].join("\n");

console.log("units:", JSON.stringify(collectHomeUnits(source), null, 0));

const locale = "hu";
const lines = source.split("\n");
const [start, end] = frontmatterRange(lines);
const out = lines
  .map((line, index) => {
    if (!(index >= start && index < end)) return line;
    const t = line.match(TRANSLATABLE_KEY);
    if (t) {
      const [, indent, key, gap, value] = t;
      if (value.length === 0) return line;
      return `${indent}${key}:${gap}${toGrave(`[${toBackticks(value)}]`)}`;
    }
    const l = line.match(LINK_KEY);
    if (l) {
      const [, indent, gap, value] = l;
      return `${indent}link:${gap}/${locale}${value}`;
    }
    return line;
  })
  .join("\n");

console.log("\n--- rewritten (translations wrapped in [] to make them visible) ---");
console.log(out);

